(2174009, 296160, 75713, '<td valign="top">his clothes/hat are quite nice.. and he has a good face.. more focus on him and maybe less people in it would have improved this shot a lot</td>', 'his clothes/hat are quite nice.. and he has a good face.. more focus on him and maybe less people in it would have improved this shot a lot', '2006-02-22 21:13:22.000000', NULL, 1),
(2174018, 298683, 75713, '<td valign="top">good choice to have a simple white background as the pattern in her stockings really stand out.</td>', 'good choice to have a simple white background as the pattern in her stockings really stand out.', '2006-02-22 21:14:41.000000', NULL, 1),
