(2174028, 298200, 10768, '<td valign="top">Like the composition and the way the greens repeat.  Would have like to see the model''s face.</td>', 'Like the composition and the way the greens repeat.  Would have like to see the model''s face.', '2006-02-22 21:17:57.000000', NULL, 1),
(2174032, 298298, 75713, '<td valign="top">a lovely model - her face is beautifully photographed and her jewellery is wonderful.... I find the white section in the bottom right hand corner distracting but this looks like a candid shot and was probably unavoidable</td>', 'a lovely model - her face is beautifully photographed and her jewellery is wonderful.... I find the white section in the bottom right hand corner distracting but this looks like a candid shot and was probably unavoidable', '2006-02-22 21:18:34.000000', NULL, 1),
(2174036, 298924, 75713, '<td valign="top">nicely photographed and a good abstract take on the fashion category</td>', 'nicely photographed and a good abstract take on the fashion category', '2006-02-22 21:19:26.000000', NULL, 1),
(2174038, 297797, 10768, '<td valign="top">Lovely pastels draws you into her dark eyes.  Well done.</td>', 'Lovely pastels draws you into her dark eyes.  Well done.', '2006-02-22 21:19:36.000000', NULL, 1),
(2174048, 298623, 75713, '<td valign="top">I like how the highlight is in his collar and his skintones are more midrange.. very well rendered photo and the model is excellent.. one tiny tiny quibble.. and I really had to look hard, is the shine inside his ear could be muted.</td>', 'I like how the highlight is in his collar and his skintones are more midrange.. very well rendered photo and the model is excellent.. one tiny tiny quibble.. and I really had to look hard, is the shine inside his ear could be muted.', '2006-02-22 21:22:33.000000', NULL, 1),
(2174053, 296915, 10768, '<td valign="top">Creative!  Love the composition and good color choice.  10</td>', 'Creative!  Love the composition and good color choice.  10', '2006-02-22 21:24:48.000000', NULL, 1),
(2174054, 298470, 10768, '<td valign="top">Love this shot.  It''s so captivating that i have to keep coming back to look some more. Background, model, b&amp;w tone are perfect.  Wish you could have cloned out the light in her reflection, but rules are rules huh?  10</td>', 'Love this shot.  It''s so captivating that i have to keep coming back to look some more. Background, model, b&w tone are perfect.  Wish you could have cloned out the light in her reflection, but rules are rules huh?  10', '2006-02-22 21:24:59.000000', NULL, 1),
(2174056, 298502, 10768, '<td valign="top">Like the ghostlike quality.  His eyes and hand draw you into the photo.  Well done!</td>', 'Like the ghostlike quality.  His eyes and hand draw you into the photo.  Well done!', '2006-02-22 21:25:07.000000', NULL, 1),
(2174057, 297061, 10768, '<td valign="top">Not my style, but you portrayed it well.  I like the choice of whitish background instead of trying to go totally dark.  The girl in the bathtub makes  it very thought provoking.  Good job!</td>', 'Not my style, but you portrayed it well.  I like the choice of whitish background instead of trying to go totally dark.  The girl in the bathtub makes  it very thought provoking.  Good job!', '2006-02-22 21:25:12.000000', NULL, 1),
(2174058, 298869, 10768, '<td valign="top">Vibrant colors, great composition, good subject for the competition.  Well done!</td>', 'Vibrant colors, great composition, good subject for the competition.  Well done!', '2006-02-22 21:25:16.000000', NULL, 1),
(2174059, 298768, 10768, '<td valign="top">Like the choice of crop.  Holds your interest.</td>', 'Like the choice of crop.  Holds your interest.', '2006-02-22 21:25:23.000000', NULL, 1),
(2174062, 298136, 10768, '<td valign="top">Nice soft focus around the subject''s face.  Very pretty model with captivating eyes.  Well done.</td>', 'Nice soft focus around the subject''s face.  Very pretty model with captivating eyes.  Well done.', '2006-02-22 21:25:55.000000', NULL, 1),
(2174064, 298492, 10768, '<td valign="top">Beautiful photograph. I think it''s more of a portrait than a fashion entry, but it is gorgeous.  love the desat colors and her content expression.</td>', 'Beautiful photograph. I think it''s more of a portrait than a fashion entry, but it is gorgeous.  love the desat colors and her content expression.', '2006-02-22 21:26:06.000000', NULL, 1),
(2174065, 298133, 10768, '<td valign="top">Composition holds interest.  Makes me want to look up to see what she''s looking at!  Ha!  I like the lighting and the sepia tone.</td>', 'Composition holds interest.  Makes me want to look up to see what she''s looking at!  Ha!  I like the lighting and the sepia tone.', '2006-02-22 21:26:09.000000', NULL, 1),
(2174068, 298682, 75713, '<td valign="top">wonderful model and her pose is excellent.. love the clothes... her skin tones appear to be a little washed out - perhaps a darker background would have helped</td>', 'wonderful model and her pose is excellent.. love the clothes... her skin tones appear to be a little washed out - perhaps a darker background would have helped', '2006-02-22 21:27:21.000000', NULL, 1),
(2174076, 298755, 75713, '<td valign="top">I like what you are going for here.. the white background &amp; foreground might not have been the best choice for this shot.. maybe a neutral grey</td>', 'I like what you are going for here.. the white background & foreground might not have been the best choice for this shot.. maybe a neutral grey', '2006-02-22 21:30:16.000000', NULL, 1),
(2174079, 298324, 45343, '<td valign="top">Very nice contrast.  Good use of "filling the frame"  Nice catch lights in the eyes.  Personally, I like the single light source look, but for fasion, I think a little reflected left side light or back light to separate from background would have been nice.  No deduction for this however... nicely done.</td>', 'Very nice contrast.  Good use of "filling the frame"  Nice catch lights in the eyes.  Personally, I like the single light source look, but for fasion, I think a little reflected left side light or back light to separate from background would have been nice.  No deduction for this however... nicely done.', '2006-02-22 21:32:06.000000', NULL, 1),
(2174083, 298200, 75713, '<td valign="top">I like this composition and use of color... it looks like you had lighting from the side - if this is true, I would have liked to have seen that back door closed as it is a bit washed out, which happens with back lighting and is distracting.</td>', 'I like this composition and use of color... it looks like you had lighting from the side - if this is true, I would have liked to have seen that back door closed as it is a bit washed out, which happens with back lighting and is distracting.', '2006-02-22 21:33:10.000000', NULL, 1),
(2174091, 298584, 45343, '<td valign="top">Intersting contrasts between model and setting.  I like it.  The right arm is in focus and eyes not... hard to say if this is motion blur or very narrow DoF.  I''ll come back and check your camera settings after the votes.   I like the pose and tilted camera angle...  It adds to drama which is also enhanced with binding of the hands.  Perhaps with a matching cloth color, though.</td>', 'Intersting contrasts between model and setting.  I like it.  The right arm is in focus and eyes not... hard to say if this is motion blur or very narrow DoF.  I''ll come back and check your camera settings after the votes.   I like the pose and tilted camera angle...  It adds to drama which is also enhanced with binding of the hands.  Perhaps with a matching cloth color, though.', '2006-02-22 21:36:43.000000', NULL, 1),
(2174095, 298293, 75713, '<td valign="top">beautiful model... the skin tones are lovely.. the blown white is distracing but the background is excellent... her hand framing her face is a bit contrived looking.. I would love to see this shot with her hand in another position - maybe on her hip?</td>', 'beautiful model... the skin tones are lovely.. the blown white is distracing but the background is excellent... her hand framing her face is a bit contrived looking.. I would love to see this shot with her hand in another position - maybe on her hip?', '2006-02-22 21:38:22.000000', NULL, 1),
(2174096, 298275, 45343, '<td valign="top">Wow... interesting spin!   The focus is sharp and clear...  well lit.  I like the catchlight in the eyes. A well executed photo... which, as you intended, is a bit disturbing.  Title just set it off.  Well done.</td>', 'Wow... interesting spin!   The focus is sharp and clear...  well lit.  I like the catchlight in the eyes. A well executed photo... which, as you intended, is a bit disturbing.  Title just set it off.  Well done.', '2006-02-22 21:39:04.000000', NULL, 1),
(2174100, 298841, 75713, '<td valign="top">I like the use of light and shadow.. the model captures my attention because of the quiet drama of her pose.. I think  the overall soft tone really works in this shot</td>', 'I like the use of light and shadow.. the model captures my attention because of the quiet drama of her pose.. I think  the overall soft tone really works in this shot', '2006-02-22 21:41:04.000000', NULL, 1),
(2174102, 296832, 45343, '<td valign="top">Very nice... reminds me of a shot for glasses store.   I like the natural framing and the texture in that frame.  The catch light in the eyes without reflection in the glasses is also quite nice.  Did you use a polarizer to help with that?</td>', 'Very nice... reminds me of a shot for glasses store.   I like the natural framing and the texture in that frame.  The catch light in the eyes without reflection in the glasses is also quite nice.  Did you use a polarizer to help with that?', '2006-02-22 21:41:43.000000', NULL, 1),
(2174105, 298992, 75713, '<td valign="top">nicely photographed</td>', 'nicely photographed', '2006-02-22 21:43:06.000000', NULL, 1),
(2174107, 296595, 75713, '<td valign="top">everything in this shot works</td>', 'everything in this shot works', '2006-02-22 21:43:35.000000', NULL, 1),
(2174109, 298680, 75713, '<td valign="top">what a fun pair of shoes</td>', 'what a fun pair of shoes', '2006-02-22 21:44:06.000000', NULL, 1),
(2174111, 297065, 45343, '<td valign="top">Nice pose.   Good model.  I like the splash of wall color.  This was a good challenge to use a nude in, which is sometimes risky on DPC.</td>', 'Nice pose.   Good model.  I like the splash of wall color.  This was a good challenge to use a nude in, which is sometimes risky on DPC.', '2006-02-22 21:44:48.000000', NULL, 1),
(2174113, 298473, 45343, '<td valign="top">Wow...  almost alien like.   I think this was a good spin on the challenge... nice and different.  well executed.  I like the texture in the mask.   Hats off to your poor model!</td>', 'Wow...  almost alien like.   I think this was a good spin on the challenge... nice and different.  well executed.  I like the texture in the mask.   Hats off to your poor model!', '2006-02-22 21:46:00.000000', NULL, 1),
(2174117, 297318, 45343, '<td valign="top">I like the addtion of the negitive space to the left.   In general, I think adding the space to the side that the person is facing would have been better, unless you are trying to get a sense of them leaving.</td>', 'I like the addtion of the negitive space to the left.   In general, I think adding the space to the side that the person is facing would have been better, unless you are trying to get a sense of them leaving.', '2006-02-22 21:48:27.000000', NULL, 1),
(2174119, 298572, 75713, '<td valign="top">a human model would have given this wonderful outfit more of an interesting composition.. the hang of the clothes seems to be off - the choice of background was a good one, as was the decision to crop the lower portion of the leg</td>', 'a human model would have given this wonderful outfit more of an interesting composition.. the hang of the clothes seems to be off - the choice of background was a good one, as was the decision to crop the lower portion of the leg', '2006-02-22 21:48:58.000000', NULL, 1),
(2174121, 298715, 75713, '<td valign="top">beautiful model, the exposure seems to be right on - the background is too busy and/or too in focus.. a shallow dof would have been an excellent choice</td>', 'beautiful model, the exposure seems to be right on - the background is too busy and/or too in focus.. a shallow dof would have been an excellent choice', '2006-02-22 21:50:36.000000', NULL, 1),
(2174126, 298924, 45343, '<td valign="top">Interesting challenge for a macro... good spin.    I like the angled line of the zipper... it give it some energy.   I think a little more contrast would have made it pop more.</td>', 'Interesting challenge for a macro... good spin.    I like the angled line of the zipper... it give it some energy.   I think a little more contrast would have made it pop more.', '2006-02-22 21:51:12.000000', NULL, 1),
(2174129, 298997, 75713, '<td valign="top">great paisley vest</td>', 'great paisley vest', '2006-02-22 21:51:39.000000', NULL, 1),
(2174136, 298067, 40667, '<td valign="top">Nice! really love the tones here, you worked it out really well! The rough texture of the fabric adds nicely to the finished touch. Love the lighting, Good job!</td>', 'Nice! really love the tones here, you worked it out really well! The rough texture of the fabric adds nicely to the finished touch. Love the lighting, Good job!', '2006-02-22 21:53:20.000000', NULL, 1),
(2174139, 298972, 75713, '<td valign="top">well thought out composition - the background, her outfit and her eyes seem to be all related in color, which I really like.. the cropping, the focus are all excellent.</td>', 'well thought out composition - the background, her outfit and her eyes seem to be all related in color, which I really like.. the cropping, the focus are all excellent.', '2006-02-22 21:54:16.000000', NULL, 1),
(2174140, 298136, 45343, '<td valign="top">Very nice.  I like the wind swept look... did you use a fan?   I like the use of DoF to bring out the eyes.I also like the shoulders and should strap serving as leading lines back to the face.   The rest of the left arm feels a bit disembodied as it leads the eye out of the frame.</td>', 'Very nice.  I like the wind swept look... did you use a fan?   I like the use of DoF to bring out the eyes.I also like the shoulders and should strap serving as leading lines back to the face.   The rest of the left arm feels a bit disembodied as it leads the eye out of the frame.', '2006-02-22 21:54:19.000000', NULL, 1),
(2174145, 298502, 45343, '<td valign="top">Interesting picture... I like it.  Make-up gives it a corpse look.  The focus is a bit soft, especially for a fashion shot.   Love the clothes.</td>', 'Interesting picture... I like it.  Make-up gives it a corpse look.  The focus is a bit soft, especially for a fashion shot.   Love the clothes.', '2006-02-22 21:56:07.000000', NULL, 1),
(2174148, 296595, 40667, '<td valign="top">Nice job! really like the angle a bit of shaddow on the face, but what can ya do. Nice job</td>', 'Nice job! really like the angle a bit of shaddow on the face, but what can ya do. Nice job', '2006-02-22 21:57:12.000000', NULL, 1),
(2174150, 297813, 45343, '<td valign="top">Kinda 80''s-ish.  with the crimped hair :)  I think a little more expression would be nice, but does fit your title.</td>', 'Kinda 80''s-ish.  with the crimped hair :)  I think a little more expression would be nice, but does fit your title.', '2006-02-22 21:57:20.000000', NULL, 1),
(2174162, 298680, 40667, '<td valign="top">Love it! Crazy heels, I''m more of a converse man, but whatever floats your boat, lol. Lightings nice, shaddow placement suits it well, overall i really like this one! , agrabs your attentionnd never lets it go. Kinda makes me wish i could get away with wearin them.... almost ;D</td>', 'Love it! Crazy heels, I''m more of a converse man, but whatever floats your boat, lol. Lightings nice, shaddow placement suits it well, overall i really like this one! , agrabs your attentionnd never lets it go. Kinda makes me wish i could get away with wearin them.... almost ;D', '2006-02-22 22:00:04.000000', NULL, 1),
(2174167, 296832, 39349, '<td valign="top">Beautiful tones and model, I like the pose, it seems natural but not too staged. Good framing with the wood around her. Well done.</td>', 'Beautiful tones and model, I like the pose, it seems natural but not too staged. Good framing with the wood around her. Well done.', '2006-02-22 22:01:12.000000', NULL, 1),
(2174178, 298133, 33361, '<td valign="top">oy vey</td>', 'oy vey', '2006-02-22 22:03:39.000000', NULL, 1),
(2174182, 298990, 75713, '<td valign="top">great pose, wonderful tones in her skin.. good shot</td>', 'great pose, wonderful tones in her skin.. good shot', '2006-02-22 22:04:03.000000', NULL, 1),
(2174184, 297975, 45343, '<td valign="top">Great use of color.  Creative clothing combo (suprised the shoes matched).  The lighting could be a little more dramatic, I think.  Overall, very nice.</td>', 'Great use of color.  Creative clothing combo (suprised the shoes matched).  The lighting could be a little more dramatic, I think.  Overall, very nice.', '2006-02-22 22:04:26.000000', NULL, 1),
(2174197, 298683, 45343, '<td valign="top">Nice High Contrast image...   I like the dramtic angled lines.   A little more separation between the shoes, visually, would have made it a little clearer.</td>', 'Nice High Contrast image...   I like the dramtic angled lines.   A little more separation between the shoes, visually, would have made it a little clearer.', '2006-02-22 22:06:03.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2174201, 298994, 75713, '<td valign="top">I like the background and the shadow.. the model is lovely and her skin tones good. the white in the strap is distracting</td>', 'I like the background and the shadow.. the model is lovely and her skin tones good. the white in the strap is distracting', '2006-02-22 22:06:45.000000', NULL, 1),
(2174209, 296612, 75713, '<td valign="top">I have no idea why you posted this in fashion but judging the photo on it''s own merits I think that the reflection of the sun inthe sand is a nice touch but the overall focus is not crisp enough</td>', 'I have no idea why you posted this in fashion but judging the photo on it''s own merits I think that the reflection of the sun inthe sand is a nice touch but the overall focus is not crisp enough', '2006-02-22 22:08:38.000000', NULL, 1),
(2174212, 298888, 45343, '<td valign="top">This is very clever.  I can see it with writting to the right as a flyer or the buisness card for a manager for "exotic dancers."   It is clean, simple and effective.  It also is a great example of how our minds fill in the blanks.  Well done.</td>', 'This is very clever.  I can see it with writting to the right as a flyer or the buisness card for a manager for "exotic dancers."   It is clean, simple and effective.  It also is a great example of how our minds fill in the blanks.  Well done.', '2006-02-22 22:08:59.000000', NULL, 1),
