(2179431, 298205, 22781, '<td valign="top">I am not 100% sure that this is fashion, but it IS a teriffic photo....</td>', 'I am not 100% sure that this is fashion, but it IS a teriffic photo....', '2006-02-24 13:09:23.000000', NULL, 1),
(2179495, 296757, 51217, '<td valign="top">beautiful</td>', 'beautiful', '2006-02-24 13:38:00.000000', NULL, 1),
