(2179532, 298990, 19672, '<td valign="top">Very nice, good post-processing.</td>', 'Very nice, good post-processing.', '2006-02-24 13:46:51.000000', NULL, 1),
(2179541, 298535, 19672, '<td valign="top">Now this looks like fashion photography. Great job. But I think I''d soften her face just a notch. (8)</td>', 'Now this looks like fashion photography. Great job. But I think I''d soften her face just a notch. (8)', '2006-02-24 13:48:35.000000', NULL, 1),
(2179549, 297061, 19672, '<td valign="top">different...<br/> <br/>but I feel the make-up detracted fromt he artistic elements...</td>', 'different... but I feel the make-up detracted fromt he artistic elements...', '2006-02-24 13:49:32.000000', NULL, 1),
(2179551, 297445, 19672, '<td valign="top">Very good advertisement look....nice. (8)</td>', 'Very good advertisement look....nice. (8)', '2006-02-24 13:50:03.000000', NULL, 1),
