(2179565, 297570, 19672, '<td valign="top">color balance issues....is her face really that red?</td>', 'color balance issues....is her face really that red?', '2006-02-24 13:53:01.000000', NULL, 1),
(2179568, 298888, 19672, '<td valign="top">cool.......</td>', 'cool.......', '2006-02-24 13:53:31.000000', NULL, 1),
(2179573, 296547, 19672, '<td valign="top">Very nice....soft feel but well done. Interesting angle. I like this a lot...gorgeous model to boot</td>', 'Very nice....soft feel but well done. Interesting angle. I like this a lot...gorgeous model to boot', '2006-02-24 13:54:22.000000', NULL, 1),
(2179599, 298412, 41091, '<td valign="top">A little too overexposed imho.  but maybe you were goign for the high key type effec...</td>', 'A little too overexposed imho.  but maybe you were goign for the high key type effec...', '2006-02-24 14:01:10.000000', NULL, 1),
(2179600, 298924, 41091, '<td valign="top">an interesting take on the challenge</td>', 'an interesting take on the challenge', '2006-02-24 14:01:50.000000', NULL, 1),
(2179601, 298095, 41091, '<td valign="top">LOL yea this takes the cake.  K</td>', 'LOL yea this takes the cake.  K', '2006-02-24 14:02:29.000000', NULL, 1),
(2179606, 298652, 41091, '<td valign="top">bit overexposed in the back white bead, but otherwise very nicely lit- light tent I''m assuming here or some major softbox work.</td>', 'bit overexposed in the back white bead, but otherwise very nicely lit- light tent I''m assuming here or some major softbox work.', '2006-02-24 14:03:34.000000', NULL, 1),
(2179609, 298729, 50530, '<td valign="top">get prepare for ribon</td>', 'get prepare for ribon', '2006-02-24 14:04:30.000000', NULL, 1),
(2179611, 298866, 19672, '<td valign="top">great shot...I really like the pose and arrangement of garments. The boots are very nice and the sharp transition of the fishnets, which create a nice moire effect to the eyes. They then sensually draw in an arch fashion right to between the model''s legs. But the use of the white button down abruptly covers with a tone of innoncence. Had the area just been exposure of undergarments it would lose a touch of innoncence and art that this photo has managed to capture nicely.  The couch, garments, dark hair all give a good monochromatic feel.<br/> <br/>My one issue is the pose/expression of the face. I don''t feel it supports the shot well. It looks bothered, even angry. A longing pose, questioning expresion, a soft smile, almost anything would have been more complimenting of this photo''s other assets. It is a wonderful shot, beautiful model. I think there may be too much tile in the forground. Remove 1/2 an inch.<br/> <br/>(9)</td>', 'great shot...I really like the pose and arrangement of garments. The boots are very nice and the sharp transition of the fishnets, which create a nice moire effect to the eyes. They then sensually draw in an arch fashion right to between the model''s legs. But the use of the white button down abruptly covers with a tone of innoncence. Had the area just been exposure of undergarments it would lose a touch of innoncence and art that this photo has managed to capture nicely.  The couch, garments, dark hair all give a good monochromatic feel. My one issue is the pose/expression of the face. I don''t feel it supports the shot well. It looks bothered, even angry. A longing pose, questioning expresion, a soft smile, almost anything would have been more complimenting of this photo''s other assets. It is a wonderful shot, beautiful model. I think there may be too much tile in the forground. Remove 1/2 an inch. (9)', '2006-02-24 14:04:39.000000', NULL, 1),
(2179614, 296915, 19672, '<td valign="top">cute</td>', 'cute', '2006-02-24 14:05:06.000000', NULL, 1),
(2179615, 298200, 41091, '<td valign="top">hmmm very intersting decision to chop the head off.  It works to focus us on her torso and lower extremity, but I would like to see the face imho.</td>', 'hmmm very intersting decision to chop the head off.  It works to focus us on her torso and lower extremity, but I would like to see the face imho.', '2006-02-24 14:05:08.000000', NULL, 1),
