(2180924, 298200, 22612, '<td valign="top">Great shot.  It leaves me wanting to see her face, but I really like how you created that since of anticipation.  The colors and set up were all really great as well.  This is one of my favorites in the challenge. 8</td>', 'Great shot.  It leaves me wanting to see her face, but I really like how you created that since of anticipation.  The colors and set up were all really great as well.  This is one of my favorites in the challenge. 8', '2006-02-24 23:02:59.000000', NULL, 1),
(2180934, 298441, 43774, '<td valign="top">Well photographed, very pro looking, one of the best in the challenge.</td>', 'Well photographed, very pro looking, one of the best in the challenge.', '2006-02-24 23:05:20.000000', NULL, 1),
(2180937, 298866, 43774, '<td valign="top">Very nice</td>', 'Very nice', '2006-02-24 23:05:30.000000', NULL, 1),
