(2180957, 298298, 43774, '<td valign="top">The white shirt(?) in front is really distracting. Should have tried to get a better angle on the girl.</td>', 'The white shirt(?) in front is really distracting. Should have tried to get a better angle on the girl.', '2006-02-24 23:14:10.000000', NULL, 1),
(2180958, 298732, 43774, '<td valign="top">Photo is blurry</td>', 'Photo is blurry', '2006-02-24 23:15:06.000000', NULL, 1),
