(2180967, 297136, 33947, '<td valign="top">Great title. Like all the different shades of teal in the shot. Compliments her black nicely. 6</td>', 'Great title. Like all the different shades of teal in the shot. Compliments her black nicely. 6', '2006-02-24 23:25:37.000000', NULL, 1),
(2180975, 298315, 33947, '<td valign="top">Nice, simple statement. Like the line, the blue, the highlights on the glass and the reflection. 10</td>', 'Nice, simple statement. Like the line, the blue, the highlights on the glass and the reflection. 10', '2006-02-24 23:29:12.000000', NULL, 1),
(2180977, 298683, 33947, '<td valign="top">VERY nice! Well cropped, good positioning and perspective. Like it. 9</td>', 'VERY nice! Well cropped, good positioning and perspective. Like it. 9', '2006-02-24 23:31:45.000000', NULL, 1),
(2180981, 298729, 33947, '<td valign="top">Nice positioning, and effective on white. Fun and festive. 6</td>', 'Nice positioning, and effective on white. Fun and festive. 6', '2006-02-24 23:33:36.000000', NULL, 1),
(2180984, 296491, 49737, '<td valign="top">Great pose, great model, great everything--except it''d be better if it were a bit clearer.  I feel like I''m seeing double and I''m losing the subject into the background because of the softness.</td>', 'Great pose, great model, great everything--except it''d be better if it were a bit clearer.  I feel like I''m seeing double and I''m losing the subject into the background because of the softness.', '2006-02-24 23:35:54.000000', NULL, 1),
(2180986, 297869, 33947, '<td valign="top">Sweet capture. Love the simplicity...and the barrette. The feet make it!! 6</td>', 'Sweet capture. Love the simplicity...and the barrette. The feet make it!! 6', '2006-02-24 23:36:32.000000', NULL, 1);
