(2181086, 298275, 30982, '<td valign="top">Novel approach!  And pretty good shot, too.  Now about the makeup application...</td>', 'Novel approach!  And pretty good shot, too.  Now about the makeup application...', '2006-02-25 00:22:46.000000', NULL, 1),
(2181087, 298992, 50147, '<td valign="top">hot</td>', 'hot', '2006-02-25 00:22:53.000000', NULL, 1),
(2181089, 298992, 30982, '<td valign="top">Very magazine-ad like.</td>', 'Very magazine-ad like.', '2006-02-25 00:23:23.000000', NULL, 1),
(2181091, 296491, 14837, '<td valign="top">Beautiful girl, great outfit, decent pose.... but it''s a way too soft for me.  This looks more like a portait then a fashion photo.</td>', 'Beautiful girl, great outfit, decent pose.... but it''s a way too soft for me.  This looks more like a portait then a fashion photo.', '2006-02-25 00:24:03.000000', NULL, 1),
(2181094, 298136, 30982, '<td valign="top">Nicely done.</td>', 'Nicely done.', '2006-02-25 00:24:41.000000', NULL, 1),
(2181097, 298293, 14837, '<td valign="top">The makeup on her face is darker and more yellow than the rest of her body.  Also, the belly button ring is a bit distracting.  Maybe somehing smaller wouldn''t draw as much attention.</td>', 'The makeup on her face is darker and more yellow than the rest of her body.  Also, the belly button ring is a bit distracting.  Maybe somehing smaller wouldn''t draw as much attention.', '2006-02-25 00:26:11.000000', NULL, 1),
(2181098, 297797, 40217, '<td valign="top">I think that this would be a stunning shot but, it is a little too bright and the darkness in the armpit really detracts from the overall feel.</td>', 'I think that this would be a stunning shot but, it is a little too bright and the darkness in the armpit really detracts from the overall feel.', '2006-02-25 00:26:28.000000', NULL, 1),
(2181099, 298991, 30982, '<td valign="top">The left side of the jacket has no definition - needed a bit more light on that side in my opinion.</td>', 'The left side of the jacket has no definition - needed a bit more light on that side in my opinion.', '2006-02-25 00:26:30.000000', NULL, 1),
(2181102, 297843, 30982, '<td valign="top">Good angle used to pose the model, and I do like the jewelry used.</td>', 'Good angle used to pose the model, and I do like the jewelry used.', '2006-02-25 00:28:10.000000', NULL, 1),
(2181104, 298034, 14837, '<td valign="top">This is a little busy.  Stripes, Spots, splattered paint and something very shiny.  I would''ve stuck with things with similar colors or patterns.</td>', 'This is a little busy.  Stripes, Spots, splattered paint and something very shiny.  I would''ve stuck with things with similar colors or patterns.', '2006-02-25 00:28:42.000000', NULL, 1),
(2181106, 297445, 30982, '<td valign="top">Should be the cover of an upscale clothing catalog.</td>', 'Should be the cover of an upscale clothing catalog.', '2006-02-25 00:30:33.000000', NULL, 1),
(2181107, 298925, 30982, '<td valign="top">Very colorful fashion!  It might stand out more against a dark, plain background.  I love the expression of your model!</td>', 'Very colorful fashion!  It might stand out more against a dark, plain background.  I love the expression of your model!', '2006-02-25 00:31:28.000000', NULL, 1),
(2181109, 298844, 30982, '<td valign="top">Good setting to depict the fashion you chose and your model did a good job.</td>', 'Good setting to depict the fashion you chose and your model did a good job.', '2006-02-25 00:32:05.000000', NULL, 1),
(2181110, 298682, 14837, '<td valign="top">there is alot of bright light here.  And it blows out her face, jeans and hand.  Very nice colors and clarity.</td>', 'there is alot of bright light here.  And it blows out her face, jeans and hand.  Very nice colors and clarity.', '2006-02-25 00:32:27.000000', NULL, 1),
(2181111, 298572, 30982, '<td valign="top">Like the colors used here.</td>', 'Like the colors used here.', '2006-02-25 00:32:52.000000', NULL, 1),
(2181114, 296915, 40217, '<td valign="top">This is a great shot, but the off-center aspect is throwing the whole appeal off. Maybe a black plate instead of a white one?</td>', 'This is a great shot, but the off-center aspect is throwing the whole appeal off. Maybe a black plate instead of a white one?', '2006-02-25 00:33:53.000000', NULL, 1),
(2181115, 298619, 14837, '<td valign="top">Too small, try to make use of the maximum pixel size allowed.</td>', 'Too small, try to make use of the maximum pixel size allowed.', '2006-02-25 00:33:54.000000', NULL, 1),
(2181116, 297975, 30982, '<td valign="top">Unique style, unique pose.  I like the foot and hand on the ground opposite each other.</td>', 'Unique style, unique pose.  I like the foot and hand on the ground opposite each other.', '2006-02-25 00:34:30.000000', NULL, 1),
