(2181120, 298951, 49475, '<td valign="top">Good pose.</td>', 'Good pose.', '2006-02-25 00:36:11.000000', NULL, 1),
(2181124, 297135, 30982, '<td valign="top">Very cute!  Love the punkish hair and the pose.  Very nice lighting on the face.  The boots kind of get lost a bit, and the background is wrinkled, though I figure you know that.</td>', 'Very cute!  Love the punkish hair and the pose.  Very nice lighting on the face.  The boots kind of get lost a bit, and the background is wrinkled, though I figure you know that.', '2006-02-25 00:38:28.000000', NULL, 1),
