INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2185408, 298200, 15511, '<td valign="top">Where''s her head?</td>', 'Where''s her head?', '2006-02-26 21:52:32.000000', NULL, 1),
(2185415, 298996, 15511, '<td valign="top">Would benefit from a light background.</td>', 'Would benefit from a light background.', '2006-02-26 21:53:44.000000', NULL, 1),
(2185432, 298462, 15511, '<td valign="top">Your cropping should be reconsidered as the backgound panels are not aligned and the headless model look is over-rated on DPC.</td>', 'Your cropping should be reconsidered as the backgound panels are not aligned and the headless model look is over-rated on DPC.', '2006-02-26 22:04:09.000000', NULL, 1),
(2185528, 298951, 29513, '<td valign="top">I like the lighting and the pose and clothes have interesting lines.  I might have opted for a different background, though.</td>', 'I like the lighting and the pose and clothes have interesting lines.  I might have opted for a different background, though.', '2006-02-26 22:55:53.000000', NULL, 1),
(2185535, 298133, 29513, '<td valign="top">Nice profile.  The background is just the right tone of off-white and the skin tones are great.  Love it.</td>', 'Nice profile.  The background is just the right tone of off-white and the skin tones are great.  Love it.', '2006-02-26 22:58:05.000000', NULL, 1),
(2185542, 298205, 29513, '<td valign="top">I like the use of the backlighting here.  I like seeing the droplets.  It might be interesting to see a longer exposure, too, to blurr out the spray. 7.</td>', 'I like the use of the backlighting here.  I like seeing the droplets.  It might be interesting to see a longer exposure, too, to blurr out the spray. 7.', '2006-02-26 23:00:46.000000', NULL, 1),
(2185553, 297643, 29513, '<td valign="top">I like the lighting and the pose.  I might have tried framing a little lower so we see more of the torso and the hands are nearer the top of the frame.  The line at right (a corner?) is a bit distracting.  I like the movement of the cloth trailing from the hands, too.</td>', 'I like the lighting and the pose.  I might have tried framing a little lower so we see more of the torso and the hands are nearer the top of the frame.  The line at right (a corner?) is a bit distracting.  I like the movement of the cloth trailing from the hands, too.', '2006-02-26 23:03:48.000000', NULL, 1),
(2185622, 298275, 49672, '<td valign="top">You know, if you photoshop in hair, and photoshop out the facial hair, and rounded the jawline a bit...bah, never mind.  You''re *still* a really ugly woman!!<br/>(Technically, this is great - good lighting, good colors, excellent "glam" fashion look - at the same time satirical and complimentary.  You get a 10.)</td>', 'You know, if you photoshop in hair, and photoshop out the facial hair, and rounded the jawline a bit...bah, never mind.  You''re *still* a really ugly woman!!(Technically, this is great - good lighting, good colors, excellent "glam" fashion look - at the same time satirical and complimentary.  You get a 10.)', '2006-02-26 23:21:31.000000', NULL, 1),
(2185627, 298535, 49672, '<td valign="top">Fantastic photo - great lighting to keep the texture in the fabric and also the skin tones on the model.</td>', 'Fantastic photo - great lighting to keep the texture in the fabric and also the skin tones on the model.', '2006-02-26 23:22:33.000000', NULL, 1),
(2185656, 296612, 48560, '<td valign="top">is that an UFO on the pier? sure looks like one from here.<br/>Too pixelated to my liking.</td>', 'is that an UFO on the pier? sure looks like one from here.Too pixelated to my liking.', '2006-02-26 23:35:49.000000', NULL, 1),
(2185721, 298832, 14448, '<td valign="top">Pose, expression, tonal control, and composition all really good, and the emphasis of the image is indeed on what she''s wearing, which seems fashionable enough to me.  Very well done.</td>', 'Pose, expression, tonal control, and composition all really good, and the emphasis of the image is indeed on what she''s wearing, which seems fashionable enough to me.  Very well done.', '2006-02-26 23:54:58.000000', NULL, 1),
(2185737, 298888, 14448, '<td valign="top">I''m not sure that it''s a bullseye with respect to the theme, but otherwise, as a graphic image, I think this is just about perfect.  I admire it tremendously -- great concept, design, and execution.</td>', 'I''m not sure that it''s a bullseye with respect to the theme, but otherwise, as a graphic image, I think this is just about perfect.  I admire it tremendously -- great concept, design, and execution.', '2006-02-26 23:59:03.000000', NULL, 1),
(2185830, 298715, 53964, '<td valign="top">The pillar right behind her face is very distracting, along with the person back there. SHE looks great, I just find it hard to keep my eye from wandering elsewhere.</td>', 'The pillar right behind her face is very distracting, along with the person back there. SHE looks great, I just find it hard to keep my eye from wandering elsewhere.', '2006-02-27 00:27:58.000000', NULL, 1),
(2185855, 298200, 53964, '<td valign="top">The bench nicely draws my eye along to the model, but it keeps going back to try to figure out what else that is on the bench.</td>', 'The bench nicely draws my eye along to the model, but it keeps going back to try to figure out what else that is on the bench.', '2006-02-27 00:35:33.000000', NULL, 1),
(2185874, 298888, 53536, '<td valign="top">The lovely composition caught my eye. Well done.</td>', 'The lovely composition caught my eye. Well done.', '2006-02-27 00:43:09.000000', NULL, 1),
(2185882, 298869, 53536, '<td valign="top">Liked the lighting and saturation here.</td>', 'Liked the lighting and saturation here.', '2006-02-27 00:45:07.000000', NULL, 1),
(2185887, 297980, 53964, '<td valign="top">Cute theme. Maybe tighter crop on the right to take out the remnant of print and bring her slightly out of center? Personally, my eye wants to go to the middle of a shot unless there''s something very strong to take it elsewhere, and he''s a little dark to automatically pull me over there, and with basic editing requirements... well, you know :)</td>', 'Cute theme. Maybe tighter crop on the right to take out the remnant of print and bring her slightly out of center? Personally, my eye wants to go to the middle of a shot unless there''s something very strong to take it elsewhere, and he''s a little dark to automatically pull me over there, and with basic editing requirements... well, you know :)', '2006-02-27 00:47:16.000000', NULL, 1),
(2185893, 296498, 53536, '<td valign="top">I like the humor and creativity.</td>', 'I like the humor and creativity.', '2006-02-27 00:48:28.000000', NULL, 1),
(2185894, 298275, 53964, '<td valign="top">I like this!</td>', 'I like this!', '2006-02-27 00:48:39.000000', NULL, 1),
(2185914, 298844, 53964, '<td valign="top">Love the pose, setting, and especially the smile, but I think the light is a little harsh.</td>', 'Love the pose, setting, and especially the smile, but I think the light is a little harsh.', '2006-02-27 00:58:58.000000', NULL, 1),
(2185923, 298609, 53964, '<td valign="top">I like the lighting, pose, framing... but for a fashion challenge the clothing dissapears... I can''t see the fashion.</td>', 'I like the lighting, pose, framing... but for a fashion challenge the clothing dissapears... I can''t see the fashion.', '2006-02-27 01:02:32.000000', NULL, 1),
(2185939, 298441, 53964, '<td valign="top">spontaneous look, but obviously carefully set up, with great lighting and all.</td>', 'spontaneous look, but obviously carefully set up, with great lighting and all.', '2006-02-27 01:08:33.000000', NULL, 1),
(2186038, 297643, 53964, '<td valign="top">Good pose, lighting, could benefit from a tight crop?</td>', 'Good pose, lighting, could benefit from a tight crop?', '2006-02-27 01:59:23.000000', NULL, 1),
(2186044, 297135, 53964, '<td valign="top">Sorry, I find the wrinkles in the backdrop very distracting...</td>', 'Sorry, I find the wrinkles in the backdrop very distracting...', '2006-02-27 02:03:59.000000', NULL, 1),
(2186046, 298623, 53964, '<td valign="top">I like how his sultry gaze meets the viewer''s eye...</td>', 'I like how his sultry gaze meets the viewer''s eye...', '2006-02-27 02:07:21.000000', NULL, 1),
(2186047, 298473, 53964, '<td valign="top">Ow, that''s gotta hurt</td>', 'Ow, that''s gotta hurt', '2006-02-27 02:08:07.000000', NULL, 1),
(2186048, 297120, 53964, '<td valign="top">Looks to me like it''s straight from a fashion ad</td>', 'Looks to me like it''s straight from a fashion ad', '2006-02-27 02:08:33.000000', NULL, 1),
(2186056, 296988, 53964, '<td valign="top">I like the colours and contrast, but the shadow on the right distracts me</td>', 'I like the colours and contrast, but the shadow on the right distracts me', '2006-02-27 02:12:04.000000', NULL, 1),
(2186228, 298755, 53964, '<td valign="top">Maybe it''s just my monitor, but I''m getting a "halo" (don''t know what it''s really called) along the left of the upper boot, making it seem glary. I like the contrast between boots and flowers, both in colour and texture, but I keep finding myself squinting :(</td>', 'Maybe it''s just my monitor, but I''m getting a "halo" (don''t know what it''s really called) along the left of the upper boot, making it seem glary. I like the contrast between boots and flowers, both in colour and texture, but I keep finding myself squinting :(', '2006-02-27 05:05:42.000000', NULL, 1),
(2186229, 297823, 53964, '<td valign="top">too much...</td>', 'too much...', '2006-02-27 05:07:15.000000', NULL, 1),
(2186230, 298315, 53964, '<td valign="top">On the whole I like it, but find myself trying to figure out what the dark band in top right is.</td>', 'On the whole I like it, but find myself trying to figure out what the dark band in top right is.', '2006-02-27 05:09:43.000000', NULL, 1),
(2186232, 296547, 53964, '<td valign="top">As a portrait I like it very much, but for the theme, the lighting loses the "fashion" part. We see the person very nicely, but the eye has to work to see the rest. Does that make sense?</td>', 'As a portrait I like it very much, but for the theme, the lighting loses the "fashion" part. We see the person very nicely, but the eye has to work to see the rest. Does that make sense?', '2006-02-27 05:12:16.000000', NULL, 1),
(2186233, 297570, 53964, '<td valign="top">Interesting fashion! :)  I''d like more DOF, personally, and find the light reflection distracting. Glasses can be a bugger!</td>', 'Interesting fashion! :)  I''d like more DOF, personally, and find the light reflection distracting. Glasses can be a bugger!', '2006-02-27 05:14:56.000000', NULL, 1),
(2186234, 297729, 53964, '<td valign="top">A little soft?</td>', 'A little soft?', '2006-02-27 05:16:11.000000', NULL, 1),
(2186235, 297065, 53964, '<td valign="top">Very striking. Personally, I''d try cropping a little tighter top and right.</td>', 'Very striking. Personally, I''d try cropping a little tighter top and right.', '2006-02-27 05:18:15.000000', NULL, 1),
(2186238, 298866, 53964, '<td valign="top">I really like this. My one nitpick is the lighting where floor and wall meet, would be nice if it weren''t so sharp. Maybe another softer light tucked under the back of the couch would work? I know you''d have fixed it with editing if you had been allowed to :)</td>', 'I really like this. My one nitpick is the lighting where floor and wall meet, would be nice if it weren''t so sharp. Maybe another softer light tucked under the back of the couch would work? I know you''d have fixed it with editing if you had been allowed to :)', '2006-02-27 05:23:07.000000', NULL, 1),
(2186296, 298577, 29513, '<td valign="top">I like the framing and the directness of the model''s gaze.  The skin tone is pretty good but the highlights seem over exposed.  I might try shooting from a slightly higher angle, just to see what it looks like.  Some light on the back drop would lessen the shadow on the right.  I like your choice of overall tint.</td>', 'I like the framing and the directness of the model''s gaze.  The skin tone is pretty good but the highlights seem over exposed.  I might try shooting from a slightly higher angle, just to see what it looks like.  Some light on the back drop would lessen the shadow on the right.  I like your choice of overall tint.', '2006-02-27 06:51:24.000000', NULL, 1),
